// На вход приходит массив items — по одному на клуб (MID, King)
// В каждом item — объект с полями: author[], text[], date[], rating_raw[], club_name[]
// (HTML-нода с returnArray:true собирает всё в массивы)

const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

const result = [];

for (const item of $input.all()) {
  const d = item.json;

  // Пропускаем пустые
  if (!d.author || !d.date) continue;

  const count = Math.max(
    d.author.length,
    d.text?.length || 0,
    d.date.length
  );

  for (let i = 0; i < count; i++) {
    const rawDate = d.date[i];
    const parsed = parseDate(rawDate);
    if (!parsed) continue;
    if (parsed < weekAgo) continue;   // старее недели — пропускаем

    result.push({
      json: {
        club_name: d.club_name?.[0] || d.club_name || 'Неизвестный клуб',
        author:    d.author[i] || '',
        text:      d.text?.[i] || '',
        date:      parsed.toISOString().slice(0, 10),
        date_raw:  rawDate,
        rating:    extractRating(d.rating_raw?.[i])
      }
    });
  }
}

// Если за неделю ничего не нашлось — отдаём пустой массив,
// AI Agent увидит и напишет "новых отзывов нет"
if (result.length === 0) {
  return [{ json: { reviews: [], message: 'За последнюю неделю новых отзывов не появилось' } }];
}

return [{ json: { reviews: result.map(r => r.json) } }];

// ---- helpers ----

function parseDate(raw) {
  if (!raw) return null;
  const s = String(raw).trim().toLowerCase();

  // 1. ISO: 2026-09-18
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) {
    const d = new Date(s);
    return isNaN(d) ? null : d;
  }

  // 2. Относительные: сегодня / вчера / N дней назад
  if (s === 'сегодня') return new Date();
  if (s === 'вчера')   return new Date(Date.now() - 86400000);
  const m = s.match(/(\d+)\s*(день|дня|дней)\s*назад/);
  if (m) return new Date(Date.now() - parseInt(m[1]) * 86400000);

  // 3. "24 ноября 2024" или "24 ноября"
  const months = {
    'января': 0, 'февраля': 1, 'марта': 2, 'апреля': 3, 'мая': 4, 'июня': 5,
    'июля': 6, 'августа': 7, 'сентября': 8, 'октября': 9, 'ноября': 10, 'декабря': 11
  };
  const m2 = s.match(/^(\d{1,2})\s+([а-яё]+)(?:\s+(\d{4}))?$/);
  if (m2) {
    const day = parseInt(m2[1], 10);
    const month = months[m2[2]];
    if (month === undefined) return null;
    const year = m2[3] ? parseInt(m2[3], 10) : new Date().getFullYear();
    return new Date(year, month, day);
  }

  return null;
}

function extractRating(raw) {
  if (!raw) return null;
  // "Оценка 5 Из 5" → 5
  const m = String(raw).match(/(\d+(?:[.,]\d+)?)/);
  return m ? parseFloat(m[1].replace(',', '.')) : null;
}

